WITH unpacked AS (SELECT id, log_ts, status_code, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace FROM app_logs WHERE TO_DATE(log_ts) >= '2025-01-21') SELECT *, AVG(status_code) OVER w_recent AS status_code_avg_2_prior, ROW_NUMBER() OVER w_recent_2 AS event_seq, LAST_VALUE(retry_count, TRUE) OVER (ORDER BY retry_count, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_retry_count FROM unpacked WINDOW w_recent AS (ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_recent_2 AS (PARTITION BY DATE_TRUNC('YEAR', log_ts) ORDER BY retry_count DESC, id)
